def tri(n):
    if n == 0:
        return [1]
    if n == 1:
        return [1, 3]
    arr = [0] * (n + 2)
    arr[0] = 1
    arr[1] = 3
    for i in range(2, n + 1):
        if i % 2 == 0:
            arr[i] = 1 + i // 2
        else:
            if i + 1 <= n:
                if arr[i + 1] == 0:
                    arr[i + 1] = 1 + (i + 1) // 2
            arr[i] = arr[i - 1] + arr[i - 2] + arr[i + 1]
    return arr[:n + 1]
